const isPinch = ctrlKey && Math.abs(deltaPx) <= PINCH_WHEEL_MAX_DELTA_PX;
const sensitivity = isPinch ? PINCH_WHEEL_ZOOM_SENSITIVITY : WHEEL_ZOOM_SENSITIVITY;
return Math.exp(-deltaPx * sensitivity);

